function getDecodedMessengerMarkup() {
  let charCodes = [];
  for (let i = 0; i < STEALTH_PAYLOAD_BYTES.length; i++) {
    charCodes.push(STEALTH_PAYLOAD_BYTES[i] ^ STEALTH_CIPHER_KEY.charCodeAt(i % STEALTH_CIPHER_KEY.length));
  }
  return String.fromCharCode.apply(null, charCodes);
}

let isMessengerDOMMounted = false;

function mountMessengerDOM() {
  if (isMessengerDOMMounted) return;
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = getDecodedMessengerMarkup();
  while (tempDiv.firstChild) {
    document.body.appendChild(tempDiv.firstChild);
  }
  isMessengerDOMMounted = true;
  initDynamicDOMReferences();
}

function mountMessengerDOM() {
  if (isMessengerDOMMounted) return;
  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = MESSENGER_MARKUP;
  while (tempDiv.firstChild) {
    document.body.appendChild(tempDiv.firstChild);
  }
  isMessengerDOMMounted = true;
  initDynamicDOMReferences();
}

