// --- Utility Functions ---
// --- Professional Scroll Management (WhatsApp / Telegram style) ---
const scrollBtn = document.getElementById('scroll-to-bottom-btn');
const scrollBadge = document.getElementById('scroll-unread-badge');
let unreadScrollCount = 0;
let isUserScrolledUp = false;

// Threshold in px — if user is within this from bottom, consider them "at bottom"
const SCROLL_THRESHOLD = 80;

function isAtBottom() {
  if (!messagesContainer) return true;
  return messagesContainer.scrollHeight - messagesContainer.scrollTop - messagesContainer.clientHeight < SCROLL_THRESHOLD;
}

function updateScrollBtn() {
  if (!scrollBtn) return;
  if (isAtBottom()) {
    scrollBtn.classList.add('hidden');
    isUserScrolledUp = false;
    unreadScrollCount = 0;
    if (scrollBadge) { scrollBadge.classList.add('hidden'); scrollBadge.textContent = '0'; }
  } else {
    scrollBtn.classList.remove('hidden');
    isUserScrolledUp = true;
  }
}

function scrollToBottom() {
  if (!messagesContainer) return;
  messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });
  unreadScrollCount = 0;
  if (scrollBadge) { scrollBadge.classList.add('hidden'); scrollBadge.textContent = '0'; }
}

// Smart scroll — only auto-scroll if user is at bottom (don't hijack if reading history)
function smartScrollToBottom() {
  if (isAtBottom()) {
    messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });
  } else {
    // User is reading old messages — just increment badge
    unreadScrollCount++;
    if (scrollBadge) {
      scrollBadge.textContent = unreadScrollCount > 99 ? '99+' : unreadScrollCount;
      scrollBadge.classList.remove('hidden');
    }
    scrollBtn && scrollBtn.classList.remove('hidden');
  }
}

// Listen to scroll events on the messages container
if (messagesContainer) {
  messagesContainer.addEventListener('scroll', updateScrollBtn, { passive: true });
}

// Click the button → scroll to bottom
if (scrollBtn) {
  scrollBtn.addEventListener('click', scrollToBottom);
}

function playNotificationSound() {
  notificationSound.currentTime = 0;
  notificationSound.play().catch(err => {
    // Browsers block autoplay audio until a user interaction occurred
    console.log('Audio autoplay blocked or failed:', err.message);
  });
}

function escapeHTML(str) {
  return str.replace(/[&<>'"]/g, 
    tag => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      "'": '&#39;',
      '"': '&quot;'
    }[tag] || tag)
  );
}

// Generate pleasing avatar background colors based on username strings
function getAvatarColor(username) {
  const colors = [
    '#2481cc', '#34c759', '#ff9500', '#af52de', 
    '#ff2d55', '#5ac8fa', '#5856d6', '#ffcc00'
  ];
  let hash = 0;
  for (let i = 0; i < username.length; i++) {
    hash = username.charCodeAt(i) + ((hash << 5) - hash);
  }
  const index = Math.abs(hash) % colors.length;
  return colors[index];
}

function formatBytes(bytes, decimals = 1) {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const dm = decimals < 0 ? 0 : decimals;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
}

async function getMediaStreamWithFallback(type) {
  const isVideo = type === 'video';

  // Constraint ladder: try progressively simpler configs until one works
  const constraintLadder = isVideo
    ? [
        // 1. HD video with echo-cancelled audio
        {
          audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
          video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'user' }
        },
        // 2. Any resolution video
        { audio: true, video: { facingMode: 'user' } },
        // 3. Completely unconstrained video
        { audio: true, video: true },
        // 4. Audio only (camera not available)
        { audio: true, video: false }
      ]
    : [
        // Voice call
        { audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } },
        { audio: true }
      ];

  let lastError = null;
  for (let i = 0; i < constraintLadder.length; i++) {
    try {
      const stream = await navigator.mediaDevices.getUserMedia(constraintLadder[i]);
      if (i > 0) {
        console.warn(`[Media] Used fallback constraint level ${i}:`, constraintLadder[i]);
        // If we fell all the way to audio-only during a video call, update callType
        if (isVideo && constraintLadder[i].video === false) {
          callType = 'audio';
          // Update UI for audio-only
          if (typeof videoStreamsContainer !== 'undefined') {
            videoStreamsContainer.classList.add('hidden');
            audioCallPlaceholder.classList.remove('hidden');
          }
          alert('📷 Camera unavailable – connected in voice-only mode.');
        }
      }
      return stream;
    } catch (err) {
      lastError = err;
      console.warn(`[Media] Constraint level ${i} failed:`, err.name, err.message);
    }
  }
  
  // Hardware / Permission access is completely blocked (common in secure in-app WebViews/Incognito with blocked permissions)
  console.warn('[Media] Hardware access completely blocked. Returning empty stream for receive-only calling.');
  showMicPermissionModal('Microphone/Camera access was denied or blocked on this device. You are connected in receive-only mode. Tap below to detect & allow microphone access.');
  return new MediaStream();
}

// --- WebRTC Peer-to-Peer Calling Logic ---
async function initiateUserCall(toSocketId, peerName, type) {
  if (peerConnection || localStream) {
    alert('You are already in an active calling session.');
    return;
  }

  console.log(`Initiating ${type} call to user ID ${toSocketId} (${peerName})`);
  activeCallTargetSocketId = toSocketId;
  callType = type;

  // Unlock Web Audio API context during user gesture
  try {
    if (!remoteAudioCtx) {
      remoteAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (remoteAudioCtx.state === 'suspended') {
      remoteAudioCtx.resume().catch(() => {});
    }
  } catch (e) {}

  if (remoteAudio) {
    remoteAudio.play().catch(() => {});
  }

  // Show active call overlay
  if (activeCallOverlay) activeCallOverlay.classList.remove('hidden');
  
  if (type === 'video') {
    if (videoStreamsContainer) videoStreamsContainer.classList.remove('hidden');
    if (audioCallPlaceholder) audioCallPlaceholder.classList.add('hidden');
    if (toggleVideoBtn) toggleVideoBtn.classList.remove('hidden');
    if (toggleQualityBtn) toggleQualityBtn.classList.remove('hidden');
    // Make call container transparent so cameras show through
    if (iosCallContainer) iosCallContainer.classList.add('video-call-active');
    // Mark Video button active
    if (iosFacetimeBtn) iosFacetimeBtn.classList.add('active-on');
    if (iosFacetimeLabel) iosFacetimeLabel.textContent = 'Camera On';
    
    // Set default labels
    isHighQuality = true;
    if (qualityBtnLabel) qualityBtnLabel.textContent = 'HD';
    if (toggleQualityBtn) {
      toggleQualityBtn.classList.remove('low-bandwidth');
      toggleQualityBtn.title = 'Switch to Low Quality (SD)';
    }
  } else {
    if (videoStreamsContainer) videoStreamsContainer.classList.add('hidden');
    if (audioCallPlaceholder) audioCallPlaceholder.classList.remove('hidden');
    if (toggleVideoBtn) toggleVideoBtn.classList.add('hidden');
    if (switchCameraBtn) switchCameraBtn.classList.add('hidden');
    if (toggleQualityBtn) toggleQualityBtn.classList.add('hidden');
    // Restore opaque background for audio call
    if (iosCallContainer) iosCallContainer.classList.remove('video-call-active');
    
    if (activeCallPeerName) activeCallPeerName.textContent = peerName;
    if (activeCallAvatar) {
      activeCallAvatar.textContent = peerName.substring(0, 2).toUpperCase();
      activeCallAvatar.style.backgroundColor = getAvatarColor(peerName);
    }
    if (activeCallStatus) activeCallStatus.textContent = 'Calling...';
  }

  try {
    // Reset state for new outgoing session
    iceCandidatesQueue = [];
    isSettingRemoteDescription = false;

    // Fetch fresh TURN credentials before creating peer connection
    await fetchTurnCredentials();

    localStream = await getMediaStreamWithFallback(type);

    if (type === 'video') {
      if (localVideo) localVideo.srcObject = localStream;
      
      // Detect multiple video cameras after permission is granted
      navigator.mediaDevices.enumerateDevices().then(devices => {
        videoInputDevices = devices.filter(d => d.kind === 'videoinput');
        console.log(`Discovered ${videoInputDevices.length} cameras:`, videoInputDevices);
        if (videoInputDevices.length > 1) {
          if (switchCameraBtn) switchCameraBtn.classList.remove('hidden');
        } else {
          if (switchCameraBtn) switchCameraBtn.classList.add('hidden');
        }
      }).catch(e => console.warn('Video device discovery error:', e));
    }


    createPeerConnection();
    logDiagnostic("P2P PC Created (Outgoing offer)...");


    // Create RTC Offer
    const offer = await peerConnection.createOffer();
    await peerConnection.setLocalDescription(offer);

    // Play Dialer sound and send socket call event
    dialingSound.currentTime = 0;
    dialingSound.play().catch(e => console.log('Audio autoplay blocked:', e.message));

    if (socket) {
      socket.emit('call-user', {
        to: toSocketId,
        offer: offer,
        type: type
      });
    }

  } catch (err) {
    console.error('Failed to get media devices:', err);
    alert('Could not access microphone or camera. Please verify permission states.');
    cleanupCallConnection();
  }
}

async function acceptIncomingCall() {
  const offerData = incomingCallOverlay ? incomingCallOverlay.dataset.offer : null;
  if (!offerData || !socket) return;
  const offer = JSON.parse(offerData);

  if (incomingCallOverlay) incomingCallOverlay.classList.add('hidden');
  ringtoneSound.pause();
  ringtoneSound.currentTime = 0;

  // Unlock Web Audio API context during user gesture
  try {
    if (!remoteAudioCtx) {
      remoteAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (remoteAudioCtx.state === 'suspended') {
      remoteAudioCtx.resume().catch(() => {});
    }
  } catch (e) {}

  if (remoteAudio) {
    remoteAudio.play().catch(() => {});
  }

  if (activeCallOverlay) activeCallOverlay.classList.remove('hidden');
  
  const peerName = incomingCallerName ? incomingCallerName.textContent : 'User';

  if (callType === 'video') {
    if (videoStreamsContainer) videoStreamsContainer.classList.remove('hidden');
    if (audioCallPlaceholder) audioCallPlaceholder.classList.add('hidden');
    if (toggleVideoBtn) toggleVideoBtn.classList.remove('hidden');
    if (toggleQualityBtn) toggleQualityBtn.classList.remove('hidden');
    // Make call container transparent so cameras show through
    if (iosCallContainer) iosCallContainer.classList.add('video-call-active');
    // Mark Video button active
    if (iosFacetimeBtn) iosFacetimeBtn.classList.add('active-on');
    if (iosFacetimeLabel) iosFacetimeLabel.textContent = 'Camera On';
    
    // Set default labels
    isHighQuality = true;
    if (qualityBtnLabel) qualityBtnLabel.textContent = 'HD';
    if (toggleQualityBtn) {
      toggleQualityBtn.classList.remove('low-bandwidth');
      toggleQualityBtn.title = 'Switch to Low Quality (SD)';
    }
  } else {
    if (videoStreamsContainer) videoStreamsContainer.classList.add('hidden');
    if (audioCallPlaceholder) audioCallPlaceholder.classList.remove('hidden');
    if (toggleVideoBtn) toggleVideoBtn.classList.add('hidden');
    if (switchCameraBtn) switchCameraBtn.classList.add('hidden');
    if (toggleQualityBtn) toggleQualityBtn.classList.add('hidden');
    // Restore opaque background for audio call
    if (iosCallContainer) iosCallContainer.classList.remove('video-call-active');
    
    if (activeCallPeerName) activeCallPeerName.textContent = peerName;
    if (activeCallAvatar) {
      activeCallAvatar.textContent = peerName.substring(0, 2).toUpperCase();
      activeCallAvatar.style.backgroundColor = getAvatarColor(peerName);
    }
    if (activeCallStatus) activeCallStatus.textContent = 'Connecting...';
  }

  try {
    // Fetch fresh TURN credentials before creating peer connection
    await fetchTurnCredentials();

    localStream = await getMediaStreamWithFallback(callType);

    if (callType === 'video') {
      if (localVideo) localVideo.srcObject = localStream;
      
      // Detect multiple video cameras after permission is granted
      navigator.mediaDevices.enumerateDevices().then(devices => {
        videoInputDevices = devices.filter(d => d.kind === 'videoinput');
        console.log(`Discovered ${videoInputDevices.length} cameras:`, videoInputDevices);
        if (videoInputDevices.length > 1) {
          if (switchCameraBtn) switchCameraBtn.classList.remove('hidden');
        } else {
          if (switchCameraBtn) switchCameraBtn.classList.add('hidden');
        }
      }).catch(e => console.warn('Video device discovery error:', e));
    }


    createPeerConnection();
    logDiagnostic("P2P PC Created (Answering call)...");
    
    isSettingRemoteDescription = true;
    await peerConnection.setRemoteDescription(new RTCSessionDescription(offer));
    isSettingRemoteDescription = false;

    // Create SDP Answer
    const answer = await peerConnection.createAnswer();
    await peerConnection.setLocalDescription(answer);

    // Process queued candidates now that both local and remote descriptions are set
    await processQueuedIceCandidates();


    socket.emit('make-answer', {
      to: activeCallTargetSocketId,
      answer: answer
    });

    if (callType === 'audio') {
      if (activeCallStatus) activeCallStatus.textContent = 'Voice Call Connected';
    }

    startCallTimer();

  } catch (err) {
    console.error('Failed to accept WebRTC call:', err);
    alert('Failed to connect call: Media access error.');
    socket.emit('end-call', { to: activeCallTargetSocketId });
    cleanupCallConnection();
  }
}

function declineIncomingCall() {
  incomingCallOverlay.classList.add('hidden');
  ringtoneSound.pause();
  ringtoneSound.currentTime = 0;

  if (socket && activeCallTargetSocketId) {
    socket.emit('reject-call', { to: activeCallTargetSocketId });
  }

  activeCallTargetSocketId = null;
  callType = null;
}

function createPeerConnection() {
  peerConnection = new RTCPeerConnection(rtcConfig);

  // Add media tracks
  localStream.getTracks().forEach(track => {
    peerConnection.addTrack(track, localStream);
  });

  // Handle ICE candidates – send all candidates including null (end-of-candidates)
  peerConnection.onicecandidate = (event) => {
    if (socket && activeCallTargetSocketId) {
      socket.emit('ice-candidate', {
        to: activeCallTargetSocketId,
        candidate: event.candidate  // null signals end of gathering
      });
    }
  };

  // ICE gathering state logging
  peerConnection.onicegatheringstatechange = () => {
    if (peerConnection) {
      console.log(`[WebRTC ICE Gathering]: ${peerConnection.iceGatheringState}`);
      logDiagnostic(`Gathering: ${peerConnection.iceGatheringState}`);
    }
  };

// Web Audio API Stream Relay for WebRTC incoming voice (bypasses browser autoplay blocks)
let remoteAudioCtx = null;
let remoteAudioSourceNode = null;

function attachRemoteAudioWebAudio(stream) {
  try {
    if (!remoteAudioCtx) {
      remoteAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (remoteAudioCtx.state === 'suspended') {
      remoteAudioCtx.resume().catch(e => console.warn('AudioContext resume error:', e));
    }
    
    if (remoteAudioSourceNode) {
      try { remoteAudioSourceNode.disconnect(); } catch (e) {}
    }
    
    if (stream && stream.getAudioTracks().length > 0) {
      remoteAudioSourceNode = remoteAudioCtx.createMediaStreamSource(stream);
      remoteAudioSourceNode.connect(remoteAudioCtx.destination);
      console.log('[WebRTC Audio] Remote audio track bound to Web Audio API destination.');
    }
  } catch (e) {
    console.warn('[WebRTC Audio] WebAudio binding error:', e.message);
  }
}

  // Handle incoming stream
  peerConnection.ontrack = (event) => {
    console.log('Received remote media stream track:', event.track.kind);
    
    // Always ensure remoteStream is initialized
    if (!remoteStream) {
      remoteStream = new MediaStream();
    }
    
    // Only add if not already present (avoid duplicate tracks on renegotiation)
    const existingIds = remoteStream.getTracks().map(t => t.id);
    if (!existingIds.includes(event.track.id)) {
      remoteStream.addTrack(event.track);
    }
    
    // Mute the remote video feed to prevent double-audio/echo on desktop
    remoteVideo.muted = true;
    
    // Force re-assign srcObject to trigger layout/pipeline updates in Chrome/Safari
    remoteVideo.srcObject = remoteStream;
    if (remoteAudio) {
      remoteAudio.muted = false;
      remoteAudio.volume = 1.0;
      remoteAudio.srcObject = remoteStream;
    }
    
    // Web Audio API destination stream binding (guarantees audio output on iOS & Bluetooth)
    attachRemoteAudioWebAudio(remoteStream);

    const unlockPlayback = () => {
      if (remoteAudioCtx && remoteAudioCtx.state === 'suspended') {
        remoteAudioCtx.resume().catch(() => {});
      }
      if (remoteAudio) remoteAudio.play().catch(() => {});
      if (remoteVideo) remoteVideo.play().catch(() => {});
    };

    unlockPlayback();
    document.addEventListener('click', unlockPlayback);
    document.addEventListener('touchstart', unlockPlayback, { passive: true });

    // Handle track unmute event
    event.track.onunmute = () => {
      unlockPlayback();
    };
    
    if (callType === 'audio') {
      activeCallStatus.textContent = 'Voice Call Active';
    }
  };

  // onnegotiationneeded: auto-renegotiate when tracks change (camera switch, screen share, etc.)
  peerConnection.onnegotiationneeded = async () => {
    // Only the call initiator (caller) should send renegotiation offers
    if (!activeCallTargetSocketId || !peerConnection) return;
    try {
      console.log('[WebRTC] onnegotiationneeded fired – sending renegotiation offer...');
      logDiagnostic('Renegotiating...');
      const offer = await peerConnection.createOffer();
      await peerConnection.setLocalDescription(offer);
      socket.emit('call-user', {
        to: activeCallTargetSocketId,
        offer: peerConnection.localDescription,
        type: callType
      });
    } catch (e) {
      console.warn('[WebRTC] onnegotiationneeded error:', e.message);
    }
  };

  // ICE connection state monitor with smart reconnect buffer
  peerConnection.oniceconnectionstatechange = () => {
    if (!peerConnection) return;
    const state = peerConnection.iceConnectionState;
    console.log(`[WebRTC ICE State]: ${state}`);
    logDiagnostic(`ICE: ${state}`);

    if (state === 'disconnected') {
      // Don't hang up instantly – give WebRTC 6s to re-bind (Wi-Fi/4G handoff)
      if (activeCallStatus) activeCallStatus.textContent = 'Reconnecting...';
      if (iceDisconnectTimeout) clearTimeout(iceDisconnectTimeout);
      iceDisconnectTimeout = setTimeout(async () => {
        if (!peerConnection || peerConnection.iceConnectionState !== 'disconnected') return;
        console.warn('[WebRTC] Still disconnected after 6s – attempting ICE restart offer...');
        logDiagnostic('ICE restart...');
        try {
          // Send a new offer with iceRestart:true so both peers re-gather candidates
          const offer = await peerConnection.createOffer({ iceRestart: true });
          await peerConnection.setLocalDescription(offer);
          socket.emit('call-user', {
            to: activeCallTargetSocketId,
            offer: peerConnection.localDescription,
            type: callType
          });
        } catch (e) {
          console.error('[WebRTC] ICE restart offer failed:', e);
          cleanupCallConnection();
        }
      }, 6000);
    } else if (state === 'connected' || state === 'completed') {
      if (iceDisconnectTimeout) { clearTimeout(iceDisconnectTimeout); iceDisconnectTimeout = null; }
      if (activeCallStatus) {
        activeCallStatus.textContent = callType === 'video' ? 'Video Call Active' : 'Voice Call Active';
      }
      logDiagnostic('Connected ✓');
    } else if (state === 'failed') {
      if (iceDisconnectTimeout) { clearTimeout(iceDisconnectTimeout); iceDisconnectTimeout = null; }
      console.warn('[WebRTC] ICE failed – attempting ICE restart...');
      logDiagnostic('ICE failed – restarting...');
      // Trigger ICE restart by sending a fresh offer
      (async () => {
        if (!peerConnection || !activeCallTargetSocketId) { cleanupCallConnection(); return; }
        try {
          const offer = await peerConnection.createOffer({ iceRestart: true });
          await peerConnection.setLocalDescription(offer);
          socket.emit('call-user', {
            to: activeCallTargetSocketId,
            offer: peerConnection.localDescription,
            type: callType
          });
        } catch (e) {
          console.error('[WebRTC] ICE restart failed:', e);
          cleanupCallConnection();
        }
      })();
    } else if (state === 'closed') {
      cleanupCallConnection();
    }
  };

  // connectionstatechange: catches Firefox/Safari-specific failures that iceConnectionState misses
  peerConnection.onconnectionstatechange = () => {
    if (!peerConnection) return;
    const state = peerConnection.connectionState;
    console.log(`[WebRTC Connection State]: ${state}`);
    if (state === 'failed') {
      console.warn('[WebRTC] connectionState failed – attempting ICE restart rather than instant disconnect.');
      logDiagnostic('Connection failed – restarting...');
      
      // Trigger ICE restart instead of instant cleanup to give cellular networks a chance to reconnect
      (async () => {
        if (!peerConnection || !activeCallTargetSocketId) { cleanupCallConnection(); return; }
        try {
          const offer = await peerConnection.createOffer({ iceRestart: true });
          await peerConnection.setLocalDescription(offer);
          socket.emit('call-user', {
            to: activeCallTargetSocketId,
            offer: peerConnection.localDescription,
            type: callType
          });
        } catch (e) {
          console.error('[WebRTC] ICE restart failed on connectionState failed:', e);
          cleanupCallConnection();
        }
      })();
    } else if (state === 'connected') {
      if (activeCallStatus) {
        activeCallStatus.textContent = callType === 'video' ? 'Video Call Active' : 'Voice Call Active';
      }
    }
  };

}

// Process any ICE candidates that arrived before the remote description was set
async function processQueuedIceCandidates() {
  if (!peerConnection) return;
  logDiagnostic(`Processing ${iceCandidatesQueue.length} queued ICE candidates...`);
  while (iceCandidatesQueue.length > 0) {
    const candidate = iceCandidatesQueue.shift();
    if (!candidate) continue;
    try {
      await peerConnection.addIceCandidate(new RTCIceCandidate(candidate));
    } catch (err) {
      console.warn('Error adding queued wrapper candidate, trying raw:', err);
      try {
        await peerConnection.addIceCandidate(candidate);
      } catch (err2) {
        console.error('Error adding queued raw ICE candidate:', err2);
      }
    }
  }
  logDiagnostic("ICE candidates processed.");
}




