// --- Merge Call Button ---
if (iosMergeBtn) iosMergeBtn.addEventListener('click', openMergeCallPanel);
if (closeMergePanelBtn) closeMergePanelBtn.addEventListener('click', closeMergePanel);
if (cancelMergeBtn) cancelMergeBtn.addEventListener('click', closeMergePanel);

function openMergeCallPanel() {
  if (!activeCallTargetSocketId) return; // Not in a call
  if (!mergeCallPanel || !mergeContactsList) return;

  // Populate with online users (excluding the current peer and self)
  mergeContactsList.innerHTML = '';
  const onlineItems = document.querySelectorAll('#user-list .user-item');
  let addedCount = 0;

  onlineItems.forEach(item => {
    const sid = item.dataset.socketId;
    const uname = item.dataset.username || item.querySelector('.user-name')?.textContent || 'User';
    if (!sid || sid === activeCallTargetSocketId) return; // skip current peer

    addedCount++;
    const row = document.createElement('div');
    row.className = 'merge-contact-item';

    const avatarDiv = document.createElement('div');
    avatarDiv.className = 'merge-contact-avatar';
    avatarDiv.style.backgroundColor = getAvatarColor(uname);
    avatarDiv.textContent = uname.substring(0, 2).toUpperCase();

    const nameSpan = document.createElement('span');
    nameSpan.className = 'merge-contact-name';
    nameSpan.textContent = uname;

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'btn-add-to-call';
    addBtn.textContent = 'Add';
    addBtn.addEventListener('click', () => {
      addBtn.disabled = true;
      addBtn.textContent = 'Calling…';
      mergeUserIntoCall(sid, uname);
      setTimeout(closeMergePanel, 600);
    });

    row.appendChild(avatarDiv);
    row.appendChild(nameSpan);
    row.appendChild(addBtn);
    mergeContactsList.appendChild(row);
  });

  if (addedCount === 0) {
    mergeContactsList.innerHTML = '<p class="merge-empty-state">No other users online to add.</p>';
  }

  mergeCallPanel.classList.remove('hidden');
  if (iosMergeBtn) iosMergeBtn.classList.add('merge-active');
}

function closeMergePanel() {
  if (mergeCallPanel) mergeCallPanel.classList.add('hidden');
  if (iosMergeBtn) iosMergeBtn.classList.remove('merge-active');
}

function mergeUserIntoCall(targetSocketId, targetName) {
  if (!socket || !localStream) {
    alert('Cannot merge: no active call stream.');
    return;
  }
  // Signal the server to invite the target user into the conference
  socket.emit('merge-call', {
    to: targetSocketId,
    from: activeCallTargetSocketId,
    callerName: currentUser,
    type: callType || 'audio'
  });
  if (activeCallStatus) activeCallStatus.textContent = `Merging ${targetName}…`;
  console.log(`[Merge] Requested merge with ${targetName} (${targetSocketId})`);
}

if (iosKeypadBtn) iosKeypadBtn.addEventListener('click', () => {
  if (iosKeypadOverlay) {
    iosKeypadOverlay.classList.remove('hidden');
    if (keypadDisplay) keypadDisplay.textContent = '';
  }
});

if (closeKeypadBtn) closeKeypadBtn.addEventListener('click', () => {
  if (iosKeypadOverlay) iosKeypadOverlay.classList.add('hidden');
});

if (hideKeypadBtn) hideKeypadBtn.addEventListener('click', () => {
  if (iosKeypadOverlay) iosKeypadOverlay.classList.add('hidden');
});

document.querySelectorAll('.dial-key').forEach(keyBtn => {
  keyBtn.addEventListener('click', () => {
    const key = keyBtn.getAttribute('data-key');
    playDTMFTone(key);
    if (keypadDisplay) keypadDisplay.textContent += key;
  });
});

// --- Microphone Permission Handling & Re-grant Logic ---
const micPermissionModal = document.getElementById('mic-permission-modal');
const grantMicPermBtn = document.getElementById('grant-mic-perm-btn');
const closeMicPermBtn = document.getElementById('close-mic-perm-btn');
const callMicWarningBtn = document.getElementById('call-mic-warning-btn');
const micPermDesc = document.getElementById('mic-perm-desc');

let isMicPermissionBlocked = false;

function showMicPermissionModal(message) {
  isMicPermissionBlocked = true;
  if (micPermDesc && message) micPermDesc.textContent = message;
  if (micPermissionModal) micPermissionModal.classList.remove('hidden');
  if (callMicWarningBtn) callMicWarningBtn.classList.remove('hidden');
}

function hideMicPermissionModal() {
  if (micPermissionModal) micPermissionModal.classList.add('hidden');
}

async function requestAndEnableMicrophone() {
  try {
    console.log('[Media] Requesting microphone permission from browser...');
    const freshStream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true }
    });

    const newAudioTrack = freshStream.getAudioTracks()[0];
    if (!newAudioTrack) throw new Error('No audio track returned');

    console.log('[Media] Microphone permission granted by user!');
    isMicPermissionBlocked = false;
    hideMicPermissionModal();
    if (callMicWarningBtn) callMicWarningBtn.classList.add('hidden');

    // If currently in a call, bind this new track to localStream & WebRTC peerConnection!
    if (localStream) {
      // Stop old dead audio tracks
      localStream.getAudioTracks().forEach(t => {
        t.stop();
        localStream.removeTrack(t);
      });
      localStream.addTrack(newAudioTrack);
    } else {
      localStream = freshStream;
    }

    if (peerConnection) {
      const senders = peerConnection.getSenders();
      const audioSender = senders.find(s => s.track && s.track.kind === 'audio');
      if (audioSender) {
        await audioSender.replaceTrack(newAudioTrack);
        console.log('[WebRTC] Replaced WebRTC audio track with new granted microphone track.');
      } else {
        peerConnection.addTrack(newAudioTrack, localStream);
        console.log('[WebRTC] Added new microphone track to active peer connection.');
      }
    }

    isMicMuted = false;
    if (iosMuteBtn) iosMuteBtn.classList.remove('muted');
    if (iosMuteLabel) iosMuteLabel.textContent = 'Mute';
    if (activeCallStatus) {
      activeCallStatus.textContent = callType === 'video' ? 'Video Call Active ✓' : 'Voice Call Active ✓';
    }

    alert('🎙️ Microphone access granted! Your voice is now transmitting.');
    return freshStream;

  } catch (err) {
    console.warn('[Media] Microphone re-grant attempt failed:', err.name, err.message);
    isMicPermissionBlocked = true;
    if (callMicWarningBtn) callMicWarningBtn.classList.remove('hidden');

    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
      showMicPermissionModal('Microphone permission is blocked in your browser site settings. Follow the instructions below to enable it.');
    } else {
      alert(`⚠️ Could not access microphone: ${err.message || 'Permission denied'}`);
    }
    return null;
  }
}

if (grantMicPermBtn) grantMicPermBtn.addEventListener('click', requestAndEnableMicrophone);
